<?php require_once __DIR__.'/includes/permissions.php';require_permission('services.manage');$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=post('action');$id=(int)post('id',0);if($a==='save'){$data=[trim((string)post('name')),trim((string)post('description')),trim((string)post('department')),post('status','Active'),(int)post('public_booking_enabled',0),max(1,(int)post('daily_capacity',8))];if(!$data[0])throw new Exception('Service name is required.');if($id){$pdo->prepare('UPDATE services SET name=?,description=?,department=?,status=?,public_booking_enabled=?,daily_capacity=? WHERE id=?')->execute([...$data,$id]);audit('UPDATE','services',$id,'Service updated');}else{$pdo->prepare('INSERT INTO services(name,description,department,status,public_booking_enabled,daily_capacity) VALUES(?,?,?,?,?,?)')->execute($data);audit('CREATE','services',(int)$pdo->lastInsertId(),'Service created');}flash('success','Service saved.');redirect(BASE_URL.'/services.php');}elseif($a==='toggle'){$pdo->prepare('UPDATE services SET status=IF(status="Active","Inactive","Active") WHERE id=?')->execute([$id]);audit('UPDATE','services',$id,'Service status changed');flash('success','Service status updated.');redirect(BASE_URL.'/services.php');}}catch(Throwable $e){$error=$e->getMessage();}}$rows=$pdo->query('SELECT * FROM services ORDER BY name')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Services Management</h1><p>Control CHO services, public booking availability and daily capacity.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Add Service</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-3"><label>Service Name *</label><input name="name" class="form-control" required></div><div class="col-md-3"><label>Department</label><input name="department" class="form-control"></div><div class="col-md-3"><label>Description</label><input name="description" class="form-control"></div><div class="col-md-1"><label>Capacity</label><input type="number" min="1" name="daily_capacity" value="8" class="form-control"></div><div class="col-md-2"><label>Public Booking</label><select name="public_booking_enabled" class="form-select"><option value="0">Disabled</option><option value="1">Enabled</option></select></div><div class="col-12"><button class="btn btn-primary">Save Service</button></div></form></div><div class="panel"><div class="panel-head"><h5>Services</h5></div><div class="table-responsive"><table class="table"><thead><tr><th>Service</th><th>Department</th><th>Status</th><th>Public</th><th>Capacity/day</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['status'])?></td><td><?=$r['public_booking_enabled']?'Yes':'No'?></td><td><?=e((string)$r['daily_capacity'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=$r['status']==='Active'?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
